@using sv_4899aca99a34468d92280671bacb0597.Models

<div class="step-indicator d-flex justify-content-between mb-4 position-relative">
    <div class="step-connector"></div>
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var status = GetStepStatus(stepIndex);
        <div class="step-item text-center @status" @onclick="() => OnStepClick(stepIndex)" role="button">
            <div class="step-circle mx-auto mb-1">
                @if (status == "completed")
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <small class="step-label">@StepNames[stepIndex]</small>
        </div>
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnNavigate { get; set; }

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnNavigate.InvokeAsync(step);
        }
    }
}

@using sv_4899aca99a34468d92280671bacb0597.Models

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label class="form-label">Full Name <span class="text-danger">*</span></label>
    <input type="text" class="form-control @ValidationClass(nameof(FullName))" @bind="FullName" @bind:event="oninput" />
    @if (Errors.ContainsKey(nameof(FullName)))
    {
        <div class="invalid-feedback d-block">@Errors[nameof(FullName)]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Email <span class="text-danger">*</span></label>
    <input type="email" class="form-control @ValidationClass(nameof(Email))" @bind="Email" @bind:event="oninput" />
    @if (Errors.ContainsKey(nameof(Email)))
    {
        <div class="invalid-feedback d-block">@Errors[nameof(Email)]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone <span class="text-danger">*</span></label>
    <input type="tel" class="form-control @ValidationClass(nameof(Phone))" @bind="Phone" @bind:event="oninput" />
    @if (Errors.ContainsKey(nameof(Phone)))
    {
        <div class="invalid-feedback d-block">@Errors[nameof(Phone)]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Address <span class="text-danger">*</span></label>
    <textarea class="form-control @ValidationClass(nameof(Address))" @bind="Address" @bind:event="oninput" rows="2"></textarea>
    @if (Errors.ContainsKey(nameof(Address)))
    {
        <div class="invalid-feedback d-block">@Errors[nameof(Address)]</div>
    }
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            <span>Validating…</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";

    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public EventCallback<string> OnEmailValidationError { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private Dictionary<string, string> Errors { get; set; } = new();
    private bool IsValidating { get; set; }

    private string ValidationClass(string field) =>
        Errors.ContainsKey(field) ? "is-invalid" : "";

    private async Task HandleNext()
    {
        Errors.Clear();

        if (string.IsNullOrWhiteSpace(FullName))
            Errors[nameof(FullName)] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email))
            Errors[nameof(Email)] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone))
            Errors[nameof(Phone)] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address))
            Errors[nameof(Address)] = "Address is required.";

        if (Errors.Count > 0) return;

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            IsValidating = false;

            if (!isValid)
            {
                Errors[nameof(Email)] = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
    }
}

@using sv_4899aca99a34468d92280671bacb0597.Models

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row mb-2">
                <div class="col-md-6">
                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" value="@Entries[index].Company"
                           @onchange="e => UpdateField(index, company: e.Value?.ToString())" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" value="@Entries[index].Title"
                           @onchange="e => UpdateField(index, title: e.Value?.ToString())" />
                </div>
            </div>

            <div class="row mb-2">
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" value="@FormatDate(Entries[index].StartDate)"
                           @onchange="e => UpdateStartDate(index, e.Value?.ToString())" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" value="@FormatDate(Entries[index].EndDate)"
                           disabled="@Entries[index].IsCurrent"
                           @onchange="e => UpdateEndDate(index, e.Value?.ToString())" />
                </div>
                <div class="col-md-4 d-flex align-items-end mb-1">
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="current-@index"
                               checked="@Entries[index].IsCurrent"
                               @onchange="e => ToggleCurrent(index, (bool)(e.Value ?? false))" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
            </div>

            <div class="mb-2">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="2" value="@Entries[index].Description"
                          @onchange="e => UpdateField(index, description: e.Value?.ToString())"></textarea>
            </div>
        </div>
    </div>
}

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }

    private string? ErrorMessage;

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private void UpdateField(int index, string? company = null, string? title = null, string? description = null)
    {
        if (company is not null) Entries[index].Company = company;
        if (title is not null) Entries[index].Title = title;
        if (description is not null) Entries[index].Description = description;
