@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";

    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public EventCallback<string> OnEmailValidationError { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private Dictionary<string, string> Errors { get; set; } = new();
    private bool IsValidating { get; set; }

    private string ValidationClass(string field) =>
        Errors.ContainsKey(field) ? "is-invalid" : "";

    private async Task HandleNext()
    {
        Errors.Clear();

        if (string.IsNullOrWhiteSpace(FullName))
            Errors[nameof(FullName)] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email))
            Errors[nameof(Email)] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone))
            Errors[nameof(Phone)] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address))
            Errors[nameof(Address)] = "Address is required.";

        if (Errors.Count > 0) return;

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            IsValidating = false;

            if (!isValid)
            {
                Errors[nameof(Email)] = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
    }
}

