@page "/apply"
@using sv_4899aca99a34468d92280671bacb0597.Models
@using sv_4899aca99a34468d92280671bacb0597.Components.Pages.Apply
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <StepIndicator CurrentStep="@currentStep" OnNavigate="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@personalFullName"
                Email="@personalEmail"
                Phone="@personalPhone"
                Address="@personalAddress"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep
                Entries="@workEntries"
                OnBack="GoBack"
                OnNext="HandleWorkNext" />
            break;

        case 2:
            <ReferencesStep
                References="@references"
                OnBack="GoBack"
                OnNext="HandleReferencesNext" />
            break;

        case 3:
            <CoverLetterStep
                CoverLetterText="@coverLetter"
                OnBack="GoBack"
                OnNext="HandleCoverLetterNext" />
            break;

        case 4:
            <ReviewStep
                Personal="@personalInfo!"
                WorkEntries="@workEntries"
                References="@references"
                CoverLetter="@coverLetter"
                OnBack="GoBack"
                OnEdit="NavigateToStep"
                OnSubmit="HandleSubmit"
                Submitted="@submitted"
                ApplicationId="@applicationId"
                IsSubmitting="@isSubmitting"
                ErrorMessage="@submitError" />
            break;
    }
</div>

@code {
    private int currentStep;

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";
    private PersonalInfo? personalInfo;

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> workEntries = new() { new() };

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = "";

    // Step 5 state
    private bool submitted;
    private int? applicationId;
    private bool isSubmitting;
    private string? submitError;

    private void NavigateToStep(int step)
    {
        if (step < currentStep)
            currentStep = step;
    }

    private void GoBack() => currentStep--;

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        personalFullName = info.FullName;
        personalEmail = info.Email;
        personalPhone = info.Phone;
        personalAddress = info.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;
        StateHasChanged();

        try
        {
            var workHistory = new WorkHistory(
                workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate ?? DateTime.MinValue,
                    e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()
            );

            var refList = references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
            ).ToList();

            var application = new JobApplication(personalInfo!, workHistory, refList, coverLetter);
            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            submitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

